=== src/web/lib/router.ts ===
import { writable, derived } from 'svelte/store';

export type RouteName =
  | 'login'
  | 'dashboard'
  | 'visits'
  | 'visitForm'
  | 'outlets'
  | 'master'
  | 'users'
  | 'notFound';

export type Route =
  | { name: 'login' }
  | { name: 'dashboard' }
  | { name: 'visits' }
  | { name: 'visitForm'; outletId: string }
  | { name: 'outlets' }
  | { name: 'master' }
  | { name: 'users' }
  | { name: 'notFound' };

function normalizePath(path: string): string {
  if (!path) return '/';
  if (!path.startsWith('/')) return '/' + path;
  return path;
}

function getPathname(): string {
  return normalizePath(window.location.pathname);
}

function parseRoute(path: string): Route {
  const normalized = normalizePath(path);

  if (normalized === '/login') return { name: 'login' };
  if (normalized === '/' || normalized === '/beranda') return { name: 'dashboard' };
  if (normalized === '/kunjungan') return { name: 'visits' };
  if (normalized.startsWith('/kunjungan/')) {
    const outletId = normalized.slice('/kunjungan/'.length);
    if (outletId) return { name: 'visitForm', outletId };
  }
  if (normalized === '/warung') return { name: 'outlets' };
  if (normalized === '/master') return { name: 'master' };
  if (normalized === '/pengguna') return { name: 'users' };

  return { name: 'notFound' };
}

export const route = writable<Route>(parseRoute(getPathname()));

export const currentPath = derived(route, ($route) => {
  switch ($route.name) {
    case 'login':
      return '/login';
    case 'dashboard':
      return '/beranda';
    case 'visits':
      return '/kunjungan';
    case 'visitForm':
      return `/kunjungan/${$route.outletId}`;
    case 'outlets':
      return '/warung';
    case 'master':
      return '/master';
    case 'users':
      return '/pengguna';
    default:
      return '/beranda';
  }
});

export function navigate(path: string, options?: { replace?: boolean }): void {
  const normalized = normalizePath(path);
  if (options?.replace) {
    history.replaceState(null, '', normalized);
  } else {
    history.pushState(null, '', normalized);
  }
  route.set(parseRoute(normalized));
}

function handleRouteChange(): void {
  route.set(parseRoute(getPathname()));
}

if (typeof window !== 'undefined') {
  window.addEventListener('popstate', handleRouteChange);
}

export function routeName(path: string): RouteName {
  return parseRoute(path).name;
}

export function isActive(path: string): boolean {
  return getPathname() === normalizePath(path);
}

export const publicRoutes = new Set(['/login']);

export type TabKey = 'beranda' | 'kunjungan' | 'warung' | 'master' | 'pengguna';

export function routeForTab(tab: TabKey): string {
  switch (tab) {
    case 'beranda':
      return '/beranda';
    case 'kunjungan':
      return '/kunjungan';
    case 'warung':
      return '/warung';
    case 'master':
      return '/master';
    case 'pengguna':
      return '/pengguna';
  }
}

