      "dependencies": [
        "ProductRepository",
        "RecipeLineRepository",
        "RawMaterialRepository"
      ],
      "domain": "hpp",
      "name": "HPPService",
      "operations": [
        {
          "description": "Computes the Harga Pokok Produksi (HPP / cost of goods sold) for a product based on its recipe lines by converting all units to base units and summing costs.",
          "functionName": "computeHPP",
          "inputs": [
            "lines: HPPRecipeLine[]"
          ],
          "name": "computeHPP",
          "outputs": [
            "hpp: number"
          ],
          "scenarios": [
            {
              "and": [
                "All units are valid and convertible to base units",
                "Math.round is applied to final result"
              ],
              "given": "A product recipe with multiple lines of raw materials in various units (ml, l, gr, kg, pcs)",
              "name": "Valid recipe lines with mixed units",
              "then": "Returns the total HPP as a rounded number in base units",
              "when": "computeHPP is called with the recipe lines"
            },
            {
              "and": [
                "Volume units convert via UNIT_TO_BASE",
                "Mass units convert via UNIT_TO_BASE",
                "Count units convert via UNIT_TO_BASE"
              ],
              "given": "Recipe lines with units from BASE_UNIT_ENUM",
              "name": "Unit conversion to base",
              "then": "Each line cost is calculated using normalized base unit quantities",
              "when": "computeHPP processes lines with different DIMENSION types (vol, mass, count)"
            },
            {
              "and": [
                "Lines array is empty"
              ],
              "given": "A product with no recipe lines",
              "name": "Empty recipe",
              "then": "Returns 0 as the HPP",
              "when": "computeHPP is called with an empty array"
            }
          ]
        },
        {
          "description": "Retrieves and enriches all recipe lines for a given product with raw material details including unit validation.",
          "functionName": "fetchRecipeLines",
          "inputs": [
            "db: DatabaseConnection",
            "productId: string"
          ],
          "name": "fetchRecipeLines",
          "outputs": [
            "lines: EnrichedRecipeLine[]"
          ],
          "scenarios": [
            {
              "and": [
                "Validates unit fields using isUnit helper",
                "Joins with raw material data"
              ],
              "given": "A product with existing recipe lines in the database",
              "name": "Product with recipe lines",
              "then": "Returns enriched recipe lines with material names, units, and quantities",
              "when": "fetchRecipeLines is called with the product ID"
            },
            {
              "and": [
                "Query uses eq filters for productId matching"
              ],
              "given": "A product with no recipe lines",
              "name": "Product without recipe lines",
              "then": "Returns an empty array",
              "when": "fetchRecipeLines is called"
            }
          ]
        },
        {
          "description": "Atomically replaces all recipe lines for a product, recalculates HPP, and updates dependent product records. This is a high-complexity transactional operation.",
          "functionName": "replaceRecipeLines",
          "inputs": [
            "db: DatabaseConnection",
            "productId: string",
            "lines: HPPRecipeLine[]"
          ],
          "name": "replaceRecipeLines",
          "outputs": [
            "updatedProduct: Product with new HPP"
          ],
          "scenarios": [
            {
              "and": [
                "Deletes existing recipe lines via db.delete with eq filter",
                "Inserts new lines with crypto.randomUUID for each line ID",
                "Validates all units using isUnit against BASE_UNIT_ENUM",
                "Fetches enriched lines via fetchRecipeLines",
                "Computes HPP via computeHPP",
                "Updates product HPP via db.update with eq filter",
                "Recalculates effectiveHPP using Math.round"
              ],
              "given": "A product with existing recipe lines and new valid recipe data",
              "name": "Replace recipe and recalculate HPP",
              "then": "Old lines are deleted, new lines are inserted, HPP is recalculated and stored, and product record is updated",
              "when": "replaceRecipeLines is called with new recipe lines"
            },
            {
              "and": [
                "Uses inArray and isNull for dependent queries",
                "Queries products using materialMap for material references"
              ],
              "given": "A product whose recipe references raw materials",
              "name": "Material reference integrity",
              "then": "All material references are resolved and validated before insertion",
              "when": "replaceRecipeLines processes lines with material IDs"
            },
            {
              "and": [
                "Transactional: all operations succeed or fail together"
              ],
              "given": "Invalid unit in one of the recipe lines",
              "name": "Invalid unit validation",
              "then": "Operation fails before persisting changes due to isUnit validation",
              "when": "replaceRecipeLines is called with malformed line data"
            }
          ]
        },
        {
          "description": "Recalculates HPP for a single product by fetching its current recipe lines, computing new HPP, and updating the product record.",
          "functionName": "recalculateHPP",
          "inputs": [
            "db: DatabaseConnection",
            "productId: string"
          ],
          "name": "recalculateHPP",
          "outputs": [
            "updatedProduct: Product with recalculated HPP"
          ],
          "scenarios": [
            {
              "and": [
                "Fetches current recipe lines via fetchRecipeLines",
                "Computes HPP via computeHPP",
                "Updates product via db.update with eq filter",
                "Uses effectiveHPP with Math.round"
              ],
              "given": "A product with existing recipe lines and potentially stale HPP",
              "name": "Recalculate existing product HPP",
              "then": "Product HPP is updated to reflect current recipe and material costs",
              "when": "recalculateHPP is called"
            },
            {
              "and": [
                "Uses inArray for batch material queries",
                "Resolves materials via materialMap.get"
              ],
              "given": "Raw material prices have changed since last HPP calculation",
              "name": "Material price change propagation",
              "then": "New HPP reflects updated material costs from database",
              "when": "recalculateHPP is called after material price updates"
            }
          ]
        },
        {
          "description": "Cascade recalculates HPP for all products whose recipes contain a specific raw material. Used when raw material prices change.",
          "functionName": "recalculateAllProductsUsingMaterial",
          "inputs": [
            "db: DatabaseConnection",
            "rawMaterialId: string"
          ],
          "name": "recalculateAllProductsUsingMaterial",
          "outputs": [
            "affectedProducts: Product[] with updated HPP"
          ],
          "scenarios": [
            {
              "and": [
                "Queries all products using the material via db.select with filters",
                "Calls recalculateHPP for each affected product",
                "May use inArray for batch operations"
              ],
              "given": "A raw material used in multiple product recipes",
              "name": "Material price change cascade",
              "then": "All products using that material have their HPP recalculated and updated",
              "when": "recalculateAllProductsUsingMaterial is called after material price change"
            },
            {
              "and": [
                "No products reference the material"
              ],
              "given": "A raw material not used in any product recipe",
              "name": "Unused material",
              "then": "No products are updated and operation completes successfully",
              "when": "recalculateAllProductsUsingMaterial is called"
            },
            {
              "and": [
                "Efficient batch querying to find affected products",
                "Sequential or parallel recalculation of each product"
              ],
              "given": "A raw material used in 50+ product recipes",
              "name": "Bulk recalculation performance",
              "then": "All affected products are updated without timeout or memory issues",
              "when": "recalculateAllProductsUsingMaterial is called for widely-used material"
            }
          ]
        }
      ],
      "purpose": "Manages Harga Pokok Produksi (HPP / Cost of Goods Sold) calculations for products based on raw material recipes. Handles unit conversion, recipe line management, and cascade recalculation when material costs change.",
      "sideEffects": [
        "Reads from recipe lines table",
        "Reads from products table",
        "Reads from raw materials table",
        "Writes to recipe lines table (delete and insert)",
        "Writes to products table (HPP update)",
        "Generates UUIDs via crypto.randomUUID"
      ]
    }
  ]
}

{
