      "operations": [
        {
          "description": "Calculates the age in hours since a visit was dropped, used for visual aging indicators in visit management.",
          "functionName": "ageHours",
          "inputs": [
            "droppedAt: string"
          ],
          "name": "Calculate visit age in hours",
