              "given": "A valid ISO timestamp string representing when a visit was dropped",
              "name": "Valid timestamp provided",
              "then": "Returns the number of hours elapsed since the dropped timestamp",
              "when": "ageHours is called"
            }
          ]
        },
        {
          "description": "Determines a color indicator (red/yellow/green) based on how long a visit has been in dropped state, enabling priority-based visit processing.",
          "functionName": "ageColor",
          "inputs": [
            "droppedAt: string"
          ],
          "name": "Determine visit age color indicator",
          "outputs": [
            "color: 'red' | 'yellow' | 'green'"
          ],
          "scenarios": [
            {
              "and": [
                "Color thresholds are based on business-defined SLA windows"
              ],
              "given": "A visit dropped timestamp",
              "name": "Visit within fresh threshold",
              "then": "Returns 'green' indicating normal priority",
              "when": "ageColor is called with recent timestamp"
            },
            {
              "and": [
                "Color thresholds are based on business-defined SLA windows"
              ],
              "given": "A visit dropped timestamp exceeding warning threshold",
              "name": "Visit exceeding warning threshold",
              "then": "Returns 'yellow' indicating elevated attention needed",
              "when": "ageColor is called with moderately aged timestamp"
            },
            {
              "and": [
                "Color thresholds are based on business-defined SLA windows"
              ],
              "given": "A visit dropped timestamp exceeding critical threshold",
              "name": "Visit exceeding critical threshold",
              "then": "Returns 'red' indicating urgent processing required",
              "when": "ageColor is called with significantly aged timestamp"
            }
          ]
        },
        {
          "description": "Calculates the great-circle distance between two GPS coordinates using the haversine formula, used for geofence validation during visit processing.",
          "functionName": "haversineM",
          "inputs": [
            "lat1: number",
            "lng1: number",
            "lat2: number",
            "lng2: number"
          ],
          "name": "Calculate haversine distance in meters",
          "outputs": [
            "distanceMeters: number"
          ],
          "scenarios": [
            {
              "and": [
                "Result is rounded to nearest meter"
              ],
              "given": "Two valid latitude/longitude coordinate pairs",
              "name": "Valid coordinates provided",
              "then": "Returns the distance between points in meters",
              "when": "haversineM is called"
            },
            {
              "and": [
                "Same point yields zero distance"
              ],
              "given": "Identical coordinates for both points",
              "name": "Same location coordinates",
              "then": "Returns 0 meters",
              "when": "haversineM is called with identical coordinates"
            }
          ]
        },
        {
          "description": "Loads all open consignment cycles for a specific outlet, filtering by outlet ID and open status to determine available cycles for visit operations.",
          "functionName": "loadOpenCycles",
          "inputs": [
            "db: database connection",
            "outletId: string/number"
          ],
          "name": "Load open consignment cycles for outlet",
          "outputs": [
            "openCycles: ConsignmentCycle[]"
          ],
          "scenarios": [
            {
              "and": [
                "Only cycles with status 'open' are returned"
              ],
              "given": "An outlet with multiple consignment cycles in various states",
              "name": "Outlet has open cycles",
              "then": "Returns array of open cycles belonging to the outlet",
              "when": "loadOpenCycles is called with valid outletId"
            },
            {
              "and": [
                "Empty array indicates no actionable cycles"
              ],
              "given": "An outlet with no open consignment cycles",
              "name": "No open cycles exist",
              "then": "Returns empty array",
              "when": "loadOpenCycles is called"
            }
          ]
        },
        {
          "description": "Processes a complete visit submission including geofence validation, cycle pickups, product drops, inventory adjustments, and visit result recording with full idempotency support.",
          "functionName": "processVisit",
          "inputs": [
            "input: ProcessVisitInput"
          ],
          "name": "Process complete visit submission",
          "outputs": [
            "result: VisitResult"
          ],
          "scenarios": [
            {
              "and": [
                "Geofence check passes or valid override reason provided",
                "All database operations succeed"
              ],
              "given": "Valid visit submission within geofence with pickup cycles and drop products",
              "name": "Successful visit with pickups and drops",
              "then": "Closes picked-up cycles, creates new open cycles for dropped products, records visit submission, and returns success result with summaries",
              "when": "processVisit is called with valid input"
            },
            {
              "and": [
                "Distance exceeds configured geofence radius",
                "No override reason provided"
              ],
              "given": "Visit submission from outside outlet geofence without override",
              "name": "Geofence violation without override",
              "then": "Returns validation error indicating geofence breach",
              "when": "processVisit is called"
            },
            {
              "and": [
                "Override reason is non-empty after trimming"
              ],
              "given": "Visit submission from outside geofence with documented override reason",
              "name": "Geofence violation with override",
              "then": "Proceeds with visit processing and records override reason",
              "when": "processVisit is called with override reason"
            },
            {
              "and": [
                "Idempotency key matches existing submission",
                "Original submission data matches"
              ],
              "given": "Duplicate visit submission with same idempotency key",
              "name": "Idempotent duplicate submission",
              "then": "Returns existing visit result without double-processing",
              "when": "processVisit is called with previously used idempotency key"
            },
            {
              "and": [
                "Pickup cycles must be in 'closed' status",
                "Pickup cycles must match visit submission idempotency key"
              ],
              "given": "Visit with pickup cycles that are not properly closed",
              "name": "Invalid pickup cycle state",
              "then": "Returns error indicating invalid cycle state for pickup",
              "when": "processVisit attempts to pick up non-closed cycles"
            },
            {
              "and": [
                "Dropped products must be active",
                "Dropped products must not be soft-deleted"
              ],
              "given": "Visit attempting to drop inactive or deleted products",
              "name": "Invalid drop products",
              "then": "Returns error filtering out invalid products from drop operation",
              "when": "processVisit includes invalid product drops"
            },
            {
              "and": [
                "Notes are trimmed before storage",
                "Geofence override reason is trimmed before storage"
              ],
              "given": "Visit submission with whitespace-padded notes and override reason",
              "name": "Trimmed text fields",
              "then": "Stores trimmed versions of text fields",
              "when": "processVisit is called"
            },
            {
              "and": [
                "All database writes are executed in batch for atomicity"
              ],
              "given": "Complex visit with multiple pickups and drops",
              "name": "Batch atomic operations",
              "then": "All cycle updates, inserts, and visit recording succeed or fail together",
              "when": "processVisit executes database operations"
            }
          ]
        }
      ],
      "purpose": "Orchestrates visit lifecycle processing including geofence validation, consignment cycle pickups and drops, inventory management, and visit result recording with idempotency guarantees.",
      "sideEffects": [
        "Reads from consignment_cycles table",
        "Reads from products table",
        "Reads from outlets table",
        "Reads from app_settings table",
        "Writes to consignment_cycles table (status updates, new cycle creation)",
        "Writes to visit_submissions table",
        "Writes to visit_drafts table",
        "Executes batched database operations",
        "Generates UUIDs for new records"
      ]
    }
  ]
}

