          "description": "Reverses a committed visit submission and reverts associated consignment cycles to their previous state.",
          "functionName": "voidVisit",
          "inputs": [
            "db: DatabaseConnection",
            "actor: Actor",
            "idempotencyKey: string",
            "reason: string"
          ],
          "name": "voidVisit",
          "outputs": ["void"],
          "scenarios": [
            {
              "and": [
                "Visit submission status updated to 'voided'",
                "Consignment cycles linked to visit submission are reverted to 'open' or 'closed' as appropriate",
                "Batch update is executed atomically"
              ],
              "given": "A committed visit submission exists with the given idempotency key, and associated consignment cycles are in 'closed' or 'open' status",
              "name": "Successful void of committed visit",
              "then": "Visit submission is marked voided, consignment cycles are reverted to previous state, and changes are persisted",
              "when": "voidVisit is called with valid idempotencyKey and non-empty reason"
            },
            {
              "and": [
                "No database state changes occur"
              ],
