              ],
              "given": "No committed visit submission exists with the given idempotency key",
              "name": "Rejection due to missing submission",
              "then": "Operation is rejected with an appropriate error",
              "when": "voidVisit is called with non-existent idempotencyKey"
            },
            {
              "and": [
                "No database state changes occur"
              ],
              "given": "The reason provided is empty or whitespace-only after trimming",
              "name": "Rejection due to invalid reason",
              "then": "Operation is rejected with a validation error",
              "when": "voidVisit is called with empty or whitespace-only reason"
            }
          ]
        },
        {
          "description": "Determines whether a newer committed visit submission exists for the same outlet after the given submission's creation time.",
          "functionName": "",
          "inputs": [
            "db: DatabaseConnection",
            "outletId: string",
            "createdAt: string"
          ],
          "name": "hasNewerCommittedSubmission",
          "outputs": ["boolean"],
          "scenarios": [
            {
              "and": [],
              "given": "The outlet has multiple committed visit submissions with different created_at timestamps",
              "name": "Newer committed submission exists",
              "then": "Returns true",
              "when": "hasNewerCommittedSubmission is called and a committed submission with created_at > given createdAt exists"
            },
            {
              "and": [],
              "given": "The outlet has no committed visit submissions with created_at after the given timestamp",
              "name": "No newer committed submission exists",
              "then": "Returns false",
              "when": "hasNewerCommittedSubmission is called"
            }
          ]
        }
      ],
      "purpose": "Provides the capability to reverse (void) a committed visit submission, including validation that no newer submission exists and reverting associated consignment cycles to their appropriate prior state.",
      "sideEffects": [
        "Updates visit_submissions table status to 'voided'",
        "Updates consignment_cycles table status from 'closed' to 'open' or maintains 'closed' based on prior state",
