          {@const input = pickups[cycle.id] ?? { good: 0, damaged: 0 }}
          {@const valid = pickupValid(cycle)}
          {@const cardClass = valid ? 'card-product' : 'card-visit border-red-200 bg-red-50 p-4'}
          <div class={cardClass}>
            <div class='mb-2 flex items-center gap-2'>
